import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.Dsl682W-.js";const k=JSON.parse('{"title":"Contributing","description":"","frontmatter":{},"headers":[],"relativePath":"docs/contributing/index.md","filePath":"contributing/index.md"}'),n={name:"docs/contributing/index.md"};function r(o,e,l,d,h,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>Kittyscape is a local development build. The runtime, support matrix, and distribution artifact are qualified together. Publication, hosting, repository ownership, and licensing remain separate decisions.</p><h2 id="start-with-evidence" tabindex="-1">Start with evidence <a class="header-anchor" href="#start-with-evidence" aria-label="Permalink to &quot;Start with evidence&quot;">​</a></h2><p>Read the repository’s <code>README.md</code> and all documents in <code>.omx/plans/</code> before changing behavior. The requirements and T01–T17 scenarios are the acceptance contract. See the <a href="./../development/compatibility-findings.html">compatibility findings</a> for selected mechanisms and unresolved gates.</p><p>Use one shared rules implementation. Keep kitty-internal access in the compatibility boundary. Do not duplicate matching logic in shell adapters. Add an adapter only when a measured reporting gap requires one.</p><h2 id="runtime-checks" tabindex="-1">Runtime checks <a class="header-anchor" href="#runtime-checks" aria-label="Permalink to &quot;Runtime checks&quot;">​</a></h2><p>From the repository or extracted source bundle:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>This runs <code>scripts/check.py</code>, the unit suite, and the installation suite. Static checks cover Python syntax, duplicate definitions, function size, argument count, line length, and branch complexity.</p><p>The tests cover matching, configuration, lifecycle, error recovery, installation preservation, and deliberate mutations of ownership and targeting guards. Graphical qualification is a separate step.</p><h2 id="qualify-the-installed-artifact" tabindex="-1">Qualify the installed artifact <a class="header-anchor" href="#qualify-the-installed-artifact" aria-label="Permalink to &quot;Qualify the installed artifact&quot;">​</a></h2><p>Build the local archive with <code>python scripts/build_release.py</code>. Keep its extracted directory and original archive together for <code>tests/runtime/installed.py</code>. The driver verifies their manifests and file hashes, installs through the generated include, and checks that kitty loaded the installed engine. It then runs the graphical scenarios and verifies restore, removal, and repeated removal.</p><p>For an X11 display and framebuffer you have already reserved and started:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/runtime/installed.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --archive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/kittyscape-0.1.0.dev1.tar.gz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/extracted/kittyscape-0.1.0.dev1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --kitty</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/kitty</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x11</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --display</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :104</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --framebuffer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/kittyscape-x11-test/frames/Xvfb_screen0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --baseline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> single</span></span></code></pre></div><p>Replace the paths and display with your owned test environment. <code>--baseline none</code> tests an original no-image window; <code>--performance</code> adds 100 measured transitions after warmup and a 60-second idle check. Use <code>--zsh-modules</code> or <code>--shell-lib-dirs</code> when a selected test binary needs its staged modules or libraries.</p><p>For Wayland, use the same archive, bundle, kitty, and shell arguments with <code>--backend wayland</code>. The runner requires a separate Hyprland instance with <code>XDG_RUNTIME_DIR</code> under <code>/tmp</code> and workspace 15 active inside that instance. It never switches the daily desktop workspace. <code>grim -T</code> captures only the exact owned kitty toplevel. Configure new fixture windows to stay on workspace 15 in that private instance.</p><p><code>tests/runtime/extended.py</code> supplies additional path, image-error, theme, and unsupported-context cases. It owns the reserved display <code>:102</code> and refuses to start when that display’s lock or socket already exists. Use its <code>--bundle</code> argument to select the code under test. The installed-artifact driver supplies the separate installation and runtime-origin proof.</p><p>For each graphical row, record artifact identity, OS, architecture, display backend, kitty/shell versions, scenario IDs, timestamps, and sanitized evidence. A workstation test does not qualify another target environment. The <a href="/kittyscape/evidence/release.json">release record</a> is the source for completed qualification rows and open gates.</p><h2 id="run-the-configured-matrix" tabindex="-1">Run the configured matrix <a class="header-anchor" href="#run-the-configured-matrix" aria-label="Permalink to &quot;Run the configured matrix&quot;">​</a></h2><p>Copy <code>tests/runtime/toolchain.example.json</code> into a private working directory and replace its placeholder paths with the test tools you have prepared. Keep conventional executable names (<code>bash</code>, <code>zsh</code>, and <code>fish</code>) inside versioned directories so kitty can identify the native shell integration.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/qualify_release.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  /path/to/kittyscape-0.1.0.dev1.tar.gz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --toolchain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/your/toolchain.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/kittyscape-release-evidence</span></span></code></pre></div><p>The template defines 96 installed fixtures: two kitty versions, six shell releases, two display backends, two baseline profiles, and interactive/login startup. This is the configured test scope, not a pass count. The batch driver extracts the archive, runs <code>installed.py</code>, and writes each completed row to <code>matrix.json</code>. It can reuse saved rows after validating their archive hash, versions, backend, baseline, and startup mode.</p><p>The installed driver’s <code>--login</code> flag selects login startup with private fixture startup files. Core scenarios include <code>pushd</code>/<code>popd</code> directory-stack transitions. Only the executed result records establish which combinations passed; consult the release record rather than inferring support from the template.</p><h2 id="isolate-desktop-testing" tabindex="-1">Isolate desktop testing <a class="header-anchor" href="#isolate-desktop-testing" aria-label="Permalink to &quot;Isolate desktop testing&quot;">​</a></h2><p>Use temporary configurations and separate kitty instances. Do not alter shell startup files, the daily-use terminal, desktop configuration, or system packages as a test prerequisite. Capture original settings and file metadata before installation, and verify removal from the packaged artifact.</p><p>For X11, choose an explicit free display number after checking both its lock and socket, including symlinks. Never use <code>Xvfb -displayfd</code>, the desktop’s display, or another test process’s display. Keep the owned Xvfb process alive for the entire run and stop only that process afterward. The installed-artifact driver expects the framebuffer to exist; it does not start Xvfb for you.</p><p>Graphical automation enables socket-only remote control in its disposable kitty configuration. Ordinary Kittyscape setup uses local key mappings and does not enable a remote-control listener.</p><h2 id="website-checks" tabindex="-1">Website checks <a class="header-anchor" href="#website-checks" aria-label="Permalink to &quot;Website checks&quot;">​</a></h2><p>The <a href="./../development/website.html">website guide</a> contains setup, build, and browser commands. Use one VitePress site, local search, system fonts, and the existing original SVG artwork. Validate root and subpath hosting, keyboard navigation, mobile widths, color contrast, and reduced motion.</p><h2 id="release-gate" tabindex="-1">Release gate <a class="header-anchor" href="#release-gate" aria-label="Permalink to &quot;Release gate&quot;">​</a></h2><p>Follow the <a href="./../development/release-checklist.html">release checklist</a>. Only completed, artifact-specific rows establish qualification. macOS arm64 remains an open gate; the release record lists any other missing evidence.</p><p>Do not publish, deploy, choose a license, or imply a public download until those actions are authorized. No contribution or publication license has been selected for this local build.</p>`,32)])])}const u=a(n,[["render",r]]);export{k as __pageData,u as default};
